<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {managementRequest} from '../api/management';
import {useAuth} from '../stores/auth';
type Item={code:string;label:string;weight:number;position:number;description?:string|null};
type Template={role_code:string;name:string;items:Item[]};
type Ruleset={id:string;version:number;status:string;checksum:string;created_at:string;config_json:any;templates:Template[]};
const auth=useAuth(),rulesets=ref<any[]>([]),selected=ref<Ruleset|null>(null),selectedId=ref(''),templates=ref<Template[]>([]),role=ref(''),tab=ref('templates'),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(false),dirty=ref(false),history=ref(false),modal=ref(false),index=ref(-1),name=ref(''),weight=ref<number|null>(null),code=ref('');
const editable=computed(()=>selected.value?.status==='DRAFT'&&auth.hasCapability('org.manage'));
const current=computed(()=>templates.value.find(t=>t.role_code===role.value));
const total=(t:Template)=>t.items.reduce((n,i)=>n+Number(i.weight||0),0);
const config=computed(()=>selected.value?.config_json??{});
const difference=computed(()=>config.value.calibration_difference);
const activeRuleset=computed(()=>rulesets.value.find(r=>r.status==='FROZEN'));
const existingDraft=computed(()=>rulesets.value.find(r=>r.status==='DRAFT'));
const differenceConfigured=computed(()=>difference.value&&Number.isFinite(difference.value.min_reviews)&&Number.isFinite(difference.value.medium_points)&&Number.isFinite(difference.value.high_points));
const dragging=ref<number|null>(null), sorting=ref(false);
const description=ref('');
function dropItem(to:number){if(!editable.value||dragging.value===null||!current.value)return;const items=current.value.items;const [item]=items.splice(dragging.value,1);if(item)items.splice(to,0,item);items.forEach((entry,index)=>{entry.position=index;});dragging.value=null;dirty.value=true;}
const ruleModal=ref(false),ruleForm=ref({high:90,excellent:95,low:60,item:30,overall:50,lowOverall:30});
const differenceModal=ref(false),differenceForm=ref<{min:number|null;medium:number|null;high:number|null}>({min:null,medium:null,high:null});
function openDifference(){const c=difference.value;differenceForm.value={min:c?.min_reviews??null,medium:c?.medium_points??null,high:c?.high_points??null};differenceModal.value=true;}
function applyDifference(){if(!selected.value)return;const f=differenceForm.value;if(f.min===null||!Number.isInteger(f.min)||f.min<2||f.medium===null||!Number.isFinite(f.medium)||f.medium<0||f.high===null||!Number.isFinite(f.high)||f.high<f.medium||f.high>100){error.value='请填写有效样本数量及差异阈值，且高等级阈值不得低于中等级。';return;}selected.value.config_json={...config.value,calibration_difference:{min_reviews:f.min,medium_points:f.medium,high_points:f.high}};dirty.value=true;error.value='';differenceModal.value=false;}
function openRules(){const c=config.value;ruleForm.value={high:(c.score?.high_bp??9000)/100,excellent:(c.score?.excellent_bp??9500)/100,low:(c.score?.low_bp??6000)/100,item:c.reasons?.item_min_chars??30,overall:c.reasons?.overall_min_chars??50,lowOverall:c.reasons?.low_overall_min_chars??30};ruleModal.value=true;}
function applyRules(){if(!selected.value)return;const f=ruleForm.value;if(![f.high,f.excellent,f.low].every(x=>Number.isInteger(x)&&x>=0&&x<=100)||f.low>f.high||f.high>f.excellent||![f.item,f.overall,f.lowOverall].every(x=>Number.isInteger(x)&&x>0&&x<=10000)){error.value='请检查分数阈值顺序及理由字数。';return;}selected.value.config_json={...config.value,score:{...config.value.score,high_bp:f.high*100,excellent_bp:f.excellent*100,low_bp:f.low*100},reasons:{...config.value.reasons,policy:'prd_v1',item_min_chars:f.item,overall_min_chars:f.overall,low_overall_min_chars:f.lowOverall}};dirty.value=true;error.value='';ruleModal.value=false;}
async function list(){rulesets.value=await managementRequest('rulesets');}
async function select(id:string){if(dirty.value&&!window.confirm('当前草稿有未保存的修改，确定切换吗？'))return;const previousRole=role.value;selectedId.value=id;loading.value=true;error.value='';try{const data=await managementRequest<Ruleset>(`rulesets/${id}`);if(selectedId.value!==id)return;selected.value=data;templates.value=structuredClone(data.templates).map(t=>({...t,items:t.items??[]}));role.value=templates.value.some(t=>t.role_code===previousRole)?previousRole:templates.value[0]?.role_code??'';dirty.value=false;}catch(e){error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;}}
async function copy(){if(!selected.value||busy.value)return;if(dirty.value&&!window.confirm('当前草稿有未保存的修改，新草稿将基于上次保存的版本创建。继续吗？'))return;busy.value=true;error.value='';try{const created=await managementRequest<any>('rulesets',{base_ruleset_id:selected.value.id});dirty.value=false;await list();await select(created.id);notice.value='已复制为新草稿，尚未影响任何周期。';}catch(e){error.value=e instanceof Error?e.message:'创建失败';}finally{busy.value=false;}}
function edit(i:number){if(!current.value)return;index.value=i;const item=current.value.items[i];name.value=item?.label??'';weight.value=item?.weight??null;description.value=item?.description??'';code.value=item?.code??'';modal.value=true;}
function apply(){if(!current.value||!name.value.trim()||!Number.isInteger(weight.value)||weight.value!<=0||weight.value!>100)return;const items=current.value.items;if(index.value<0){const newCode='custom_'+crypto.randomUUID().replaceAll('-','');items.push({code:newCode,label:name.value.trim(),weight:weight.value!,position:items.length,description:description.value.trim()||null});}else{items[index.value]={...items[index.value]!,label:name.value.trim(),weight:weight.value!,description:description.value.trim()||null};}dirty.value=true;modal.value=false;}
function remove(i:number){if(!current.value||!window.confirm(`确定删除“${current.value.items[i]?.label}”吗？`))return;current.value.items.splice(i,1);dirty.value=true;}
function move(i:number,delta:number){if(!current.value)return;const items=current.value.items,j=i+delta;if(j<0||j>=items.length)return;[items[i],items[j]]=[items[j]!,items[i]!];dirty.value=true;}
async function save(){if(!selected.value||!editable.value)return;if(templates.value.some(t=>total(t)!==100)){error.value='每种模板的权重合计必须为 100%。';return;}busy.value=true;error.value='';try{await managementRequest(`rulesets/${selected.value.id}`,{config:config.value,templates:templates.value,expected_checksum:selected.value.checksum},'PATCH');dirty.value=false;await select(selectedId.value);notice.value='草稿已保存。';}catch(e){error.value=e instanceof Error?e.message:'保存失败';}finally{busy.value=false;}}
async function freeze(){if(!selected.value||dirty.value||!window.confirm('确认校验并冻结当前草稿？冻结后不能修改。'))return;busy.value=true;error.value='';try{await managementRequest(`rulesets/${selected.value.id}/freeze`,{});await list();await select(selectedId.value);notice.value='规则集已冻结。';}catch(e){error.value=e instanceof Error?e.message:'冻结失败';}finally{busy.value=false;}}
async function removeDraft(){if(!selected.value||!editable.value||!window.confirm('确定删除此未使用的规则草稿？'))return;busy.value=true;error.value='';try{await managementRequest(`rulesets/${selected.value.id}`,undefined,'DELETE');dirty.value=false;selected.value=null;await list();if(rulesets.value[0])await select(rulesets.value[0].id);notice.value='草稿已删除。';}catch(e){error.value=e instanceof Error?e.message:'删除失败';}finally{busy.value=false;}}
onMounted(async()=>{try{await list();const initial=rulesets.value.find(r=>r.status==='FROZEN')??rulesets.value[0];if(initial)await select(initial.id);}catch(e){error.value=e instanceof Error?e.message:'加载失败';}});
</script>
<template>
<div class="rules">
 <p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p>
 <section class="summary">
  <div class="summary-main"><span class="summary-icon">▦</span><div><small>当前查看版本</small><h2>规则集 v{{selected?.version??'—'}} <span class="badge" :class="{draft:selected?.status==='DRAFT'}">{{selected?.status==='FROZEN'?'已冻结':selected?.status==='DRAFT'?'草稿':'—'}}</span></h2><label class="version-label">切换版本 <select :value="selectedId" @change="select(($event.target as HTMLSelectElement).value)"><option v-for="r in rulesets" :key="r.id" :value="r.id">v{{r.version}} · {{r.status==='FROZEN'?'已冻结':'草稿'}}</option></select></label></div></div>
  <div class="summary-meta"><span>最新冻结版本：<b>{{activeRuleset?'v'+activeRuleset.version:'暂无'}}</b></span><span>适用周期：<b>请以周期引用的规则版本为准</b></span></div>
  <div class="actions"><button class="button" @click="history=true">查看版本记录</button><button v-if="auth.hasCapability('org.manage') && existingDraft && selected?.status!=='DRAFT'" class="button" @click="select(existingDraft.id)">编辑已有草稿 v{{existingDraft.version}}</button><button v-if="auth.hasCapability('org.manage')" class="button primary" :disabled="busy||!selected" @click="copy">复制为新草稿</button></div>
 </section>
 <nav class="tabs" aria-label="规则分类"><button :class="{active:tab==='templates'}" @click="tab='templates'">评价模板</button><button :class="{active:tab==='scores'}" @click="tab='scores'">评分规则</button><button :class="{active:tab==='exceptions'}" @click="tab='exceptions'">异常判定规则</button></nav>
 <p v-if="loading" class="panel">正在加载规则…</p>
 <template v-else-if="selected">
  <section v-if="tab==='templates'" class="panel layout">
   <aside><h3>评价模板（{{templates.length}}）</h3><button v-for="t in templates" :key="t.role_code" class="template-card" :class="{chosen:role===t.role_code}" @click="role=t.role_code"><span class="template-icon">◇</span><span><b>{{t.name}}</b> <small>{{t.role_code}}</small><span class="template-meta">{{t.items.length}} 个维度 · 权重 {{total(t)}}%</span></span></button></aside>
   <div v-if="current" class="template-content"><div class="content-heading"><h2>{{current.name}} <small>{{current.role_code}}</small></h2><span v-if="!editable" class="read-only">{{selected?.status==='FROZEN'?'已冻结，复制为草稿后可编辑':'当前账号没有编辑权限'}}</span></div>
    <div class="scroll table-box"><table><thead><tr><th>序号</th><th>评价维度</th><th>权重（%）</th><th>维度说明</th><th>操作</th></tr></thead><tbody><tr v-for="(i,n) in current.items" :key="i.code" :draggable="editable && sorting" @dragstart="dragging=n" @dragover.prevent @drop.prevent="dropItem(n)" @dragend="dragging=null"><td><span v-if="editable&&sorting" class="drag">⋮⋮</span>{{n+1}}</td><td><b>{{i.label}}</b></td><td>{{i.weight}}</td><td class="muted">{{i.description || "—"}}</td><td><template v-if="editable"><button class="text-action" @click="edit(n)">编辑</button><button class="text-action danger" @click="remove(n)">删除</button></template><span v-else class="muted">只读</span></td></tr></tbody></table>
    <div class="table-footer"><div><button v-if="editable" class="button" @click="edit(-1)">＋ 新增维度</button><button v-if="editable" class="button" @click="sorting=!sorting">{{sorting?'完成排序':'调整顺序'}}</button></div><span>权重合计： <b class="weight-badge" :class="{invalid:total(current)!==100}">{{total(current)}}%</b></span></div></div><p v-if="sorting" class="muted sort-tip">拖动行左侧手柄调整顺序。</p>
   </div><div v-else class="muted">当前规则集没有模板。</div>
  </section>
  <section v-else-if="tab==='scores'" class="panel rule-panel"><h2>评分规则</h2><div class="scroll table-box"><table><thead><tr><th>规则类型</th><th>评分条件</th><th>理由要求</th><th>适用范围</th><th>操作</th></tr></thead><tbody>
   <tr><td><b>高分</b></td><td>单项或综合分 ≥ {{(config.score?.high_bp??9000)/100}} 分</td><td>{{config.reasons?.policy==='prd_v1'? '单项至少 '+config.reasons.item_min_chars+' 字；综合高分整体至少 '+config.reasons.overall_min_chars+' 字并关联月报':'按历史单项理由规则校验'}}</td><td>自评、他评</td><td><button v-if="editable" class="text-action" @click="openRules">编辑</button><span v-else class="muted">只读</span></td></tr>
   <tr><td><b>重点高分</b></td><td>综合或单项 ≥ {{(config.score?.excellent_bp??9500)/100}} 分</td><td>重点抽查，不自动判错</td><td>自评、他评</td><td><button v-if="editable" class="text-action" @click="openRules">编辑</button><span v-else class="muted">只读</span></td></tr>
   <tr><td><b>低分</b></td><td>单项 &lt; {{(config.score?.low_bp??6000)/100}} 分</td><td>{{config.reasons?.policy==='prd_v1'?'整体说明至少 '+config.reasons.low_overall_min_chars+' 字':'按历史单项理由规则校验'}}</td><td>自评、他评</td><td><button v-if="editable" class="text-action" @click="openRules">编辑</button><span v-else class="muted">只读</span></td></tr>
  </tbody></table></div></section>
  <section v-else class="panel rule-panel"><h2>异常判定规则</h2><div class="scroll table-box"><table><thead><tr><th>异常类型</th><th>触发条件</th><th>核验要求</th><th>应用状态</th><th>操作</th></tr></thead><tbody>
   <tr><td><b>高分核验</b></td><td>综合分 ≥ {{(config.score?.high_bp??9000)/100}} 分</td><td>依据规则核验</td><td><span class="status neutral">按现有扫描逻辑</span></td><td><button v-if="editable" class="text-action" @click="openRules">编辑</button><span v-else class="muted">只读</span></td></tr>
   <tr><td><b>重点高分核验</b></td><td>综合或单项 ≥ {{(config.score?.excellent_bp??9500)/100}} 分</td><td>重点抽查</td><td><span class="status neutral">按现有扫描逻辑</span></td><td><button v-if="editable" class="text-action" @click="openRules">编辑</button><span v-else class="muted">只读</span></td></tr>
   <tr><td><b>低分核验</b></td><td>单项 &lt; {{(config.score?.low_bp??6000)/100}} 分</td><td>依据规则核验</td><td><span class="status neutral">按现有扫描逻辑</span></td><td><button v-if="editable" class="text-action" @click="openRules">编辑</button><span v-else class="muted">只读</span></td></tr>
   <tr><td><b>评价理由不完整</b></td><td>评分理由不满足规则要求</td><td>补充评分依据</td><td><span class="status" :class="config.reasons?.policy==='prd_v1'?'enabled':'neutral'">{{config.reasons?.policy==='prd_v1'?'已启用':'历史规则'}}</span></td><td><button v-if="editable" class="text-action" @click="openRules">编辑</button><span v-else class="muted">只读</span></td></tr>
   <tr><td><b>自评与他评差异</b></td><td>{{differenceConfigured?'中等级 ≥ '+difference.medium_points+' 分，高等级 ≥ '+difference.high_points+' 分':'未配置'}}</td><td>{{differenceConfigured?'有效他评至少 '+difference.min_reviews+' 条':'配置后方可触发'}}</td><td><span class="status" :class="differenceConfigured?'enabled':'neutral'">{{differenceConfigured?'已配置':'未配置'}}</span></td><td><button v-if="editable" class="text-action" @click="openDifference">配置</button><span v-else class="muted">只读</span></td></tr>
  </tbody></table></div></section>
  <div v-if="editable" class="bottom"><button class="button" :disabled="busy||!dirty" @click="select(selectedId)">取消修改</button><button class="button primary" :disabled="busy||!dirty" @click="save">保存草稿</button><button class="button" :disabled="busy||dirty" @click="freeze">校验并冻结</button><button class="button" :disabled="busy||dirty" @click="removeDraft">删除草稿</button></div>
 </template>
 <div v-if="differenceModal" class="overlay" @click.self="differenceModal=false"><section class="dialog" role="dialog" aria-modal="true"><h2>配置自他评差异</h2><label>最少有效他评数 <em>*</em><input v-model.number="differenceForm.min" type="number" min="2"></label><label>中等级差值（分） <em>*</em><input v-model.number="differenceForm.medium" type="number" min="0" max="100"></label><label>高等级差值（分） <em>*</em><input v-model.number="differenceForm.high" type="number" min="0" max="100"></label><p v-if="error" class="error">{{error}}</p><div class="dialog-actions"><button class="button" @click="differenceModal=false">取消</button><button class="button primary" @click="applyDifference">确定</button></div></section></div>
 <div v-if="ruleModal" class="overlay" @click.self="ruleModal=false"><section class="dialog" role="dialog" aria-modal="true"><h2>编辑评分规则</h2><p class="muted">规则集 v{{selected?.version}} · 草稿</p><label>高分阈值 <em>*</em><input v-model.number="ruleForm.high" type="number" min="0" max="100"></label><label>重点高分阈值 <em>*</em><input v-model.number="ruleForm.excellent" type="number" min="0" max="100"></label><label>低分阈值（低于） <em>*</em><input v-model.number="ruleForm.low" type="number" min="0" max="100"></label><label>高分单项理由字数 <em>*</em><input v-model.number="ruleForm.item" type="number" min="1"></label><label>综合高分整体说明字数 <em>*</em><input v-model.number="ruleForm.overall" type="number" min="1"></label><label>低分整体说明字数 <em>*</em><input v-model.number="ruleForm.lowOverall" type="number" min="1"></label><p v-if="error" class="error">{{error}}</p><div class="dialog-actions"><button class="button" @click="ruleModal=false">取消</button><button class="button primary" @click="applyRules">确定</button></div></section></div>
 <div v-if="modal" class="overlay" @click.self="modal=false"><section class="dialog" role="dialog" aria-modal="true"><h2>{{index<0?'新增维度':'编辑评价维度'}}</h2><p class="muted">所属模板：{{current?.name}}（{{current?.role_code}}）</p><label>维度名称 <em>*</em><input v-model.trim="name" maxlength="100"></label><label>权重（%） <em>*</em><input v-model.number="weight" type="number" min="1" max="100" step="1"></label><label>维度说明<textarea v-model.trim="description" maxlength="2000" rows="3"></textarea></label><p class="muted">保存草稿时，每种模板的权重合计须为 100%。</p><div class="dialog-actions"><button class="button" @click="modal=false">取消</button><button class="button primary" :disabled="!name||!Number.isInteger(weight)||!weight||weight<1||weight>100" @click="apply">确定</button></div></section></div>
 <div v-if="history" class="overlay" @click.self="history=false"><section class="dialog" role="dialog" aria-modal="true"><h2>规则版本记录</h2><p v-for="r in rulesets" :key="r.id">v{{r.version}} · {{r.status==='FROZEN'?'已冻结':'草稿'}} · {{r.frozen_at?new Date(r.frozen_at).toLocaleString():'历史记录未提供'}} · {{r.frozen_by_name??'发布人未记录'}}</p><div class="dialog-actions"><button class="button" @click="history=false">关闭</button></div></section></div>
</div>
</template>

